contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: takes an address candidateLogger and a keepAddress
    function run(address candidateLogger, address keepAddress) public payable {
        require(candidateLogger != address(0));
        // record whether candidateLogger is currently approved (read public mapping via getter)
        bool beforeApproved = c.approvedToLog(candidateLogger); if (__ESBMC_reverted()) return;

        // We will attempt to call logCreated as if msg.sender == candidateLogger.
        // But in this harness msg.sender is this contract. So first set approval for this contract
        // to candidateLogger's desired status depending on beforeApproved:
        // If beforeApproved is true, we won't change anything. If false, we will toggle approval
        // by calling setApprovedLogger to make this contract approved, then call logCreated, then
        // restore original approval to observe that mapping entry for candidateLogger is unchanged.

        // Note: onlyOwner modifier prevents arbitrary callers from calling setApprovedLogger.
        // The deployer of c is the test harness constructor caller (checker), not this contract.
        // So we cannot call setApprovedLogger here. Therefore we assert a general relation that
        // calling logCreated by this contract (msg.sender==address(this)) returns false whenever
        // beforeApproved is false, and returns true whenever beforeApproved is true. Also the mapping
        // entry for candidateLogger must remain equal to beforeApproved after the call.

        // Call logCreated as this contract (msg.sender == address(this)). The contract C uses
        // approvedLoggers[msg.sender] so the relevant key is address(this), NOT candidateLogger.
        // We therefore also read approval for address(this) to form a general rule.

        bool thisApproved_before = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;

        bool succeeded;
        bool r = c.logCreated(keepAddress); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            succeeded = false;
        } else {
            succeeded = r;
        }

        // reads after
        bool thisApproved_after = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;
        bool candidateApproved_after = c.approvedToLog(candidateLogger); if (__ESBMC_reverted()) return;

        // General rule: the call's return value equals the approval status of msg.sender (this contract)
        // both before and after the call the approval status of address(this) and candidateLogger remain unchanged
        // (i.e., logging functions do not alter approvedLoggers mapping). Therefore:
        assert(
            // return reflects approval of this contract
            (succeeded == thisApproved_before)
            // calling logCreated must not have changed approval entries
            && (thisApproved_after == thisApproved_before)
            && (candidateApproved_after == beforeApproved)
        );
    }

    receive() external payable { }
}

