pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(address candidateLogger, address keepAddress) internal {
        vm.assume(candidateLogger != address(0));
        bool beforeApproved;
        try c.approvedToLog(candidateLogger) returns (bool __r) { beforeApproved = __r; } catch { return; }
        bool thisApproved_before;
        try c.approvedToLog(address(this)) returns (bool __r) { thisApproved_before = __r; } catch { return; }
        bool succeeded;
        try c.logCreated(keepAddress) returns (bool r) {
            succeeded = r;
        } catch {
            succeeded = false;
        }
        bool thisApproved_after;
        try c.approvedToLog(address(this)) returns (bool __r) { thisApproved_after = __r; } catch { return; }
        bool candidateApproved_after;
        try c.approvedToLog(candidateLogger) returns (bool __r) { candidateApproved_after = __r; } catch { return; }
        assertTrue((succeeded == thisApproved_before)
            // calling logCreated must not have changed approval entries
            && (thisApproved_after == thisApproved_before)
            && (candidateApproved_after == beforeApproved));
    }

    function testFuzz_run(address candidateLogger, address keepAddress) public {
        vm.assume(candidateLogger.code.length == 0 && uint160(candidateLogger) > 0xffff && candidateLogger != address(this) && candidateLogger != address(c) && candidateLogger != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && candidateLogger != 0x000000000000000000636F6e736F6c652e6c6f67 && candidateLogger != 0x4e59b44847b379578588920cA78FbF26c0B4956C && candidateLogger != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(keepAddress.code.length == 0 && uint160(keepAddress) > 0xffff && keepAddress != address(this) && keepAddress != address(c) && keepAddress != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && keepAddress != 0x000000000000000000636F6e736F6c652e6c6f67 && keepAddress != 0x4e59b44847b379578588920cA78FbF26c0B4956C && keepAddress != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(candidateLogger, keepAddress);
    }

    receive() external payable { }
}
